import re
def analyze(path, lockpat, extra=None):
    try: lines=open(path,errors='replace').read().split('\n')
    except Exception as e: print(path,"ERR",e); return
    print("#"*10, path)
    # build function map: lines at col 0 that look like definitions
    defs=[]
    for i,l in enumerate(lines):
        if re.match(r'^[A-Za-z_][A-Za-z0-9_ \t\*]*\(', l) and not l.rstrip().endswith(';') and not l.lstrip().startswith(('if','for','while','switch','return','else','}')):
            defs.append((i,l.strip().split('(')[0].split()[-1]))
    def fn(idx):
        name='?'
        for d,l in defs:
            if d<=idx: name=l
            else: break
        return name
    for i,l in enumerate(lines):
        if re.search(r'spin_(un)?lock(_bh|_irqsave|_irq)?\s*\(\s*'+lockpat,l) or (extra and re.search(extra,l)):
            if 'unlock' in l and 'lock' in l.split('(')[0]:
                continue
            if re.search(r'spin_lock',l):
                print(f"  L{i+1} [{fn(i)}] {l.strip()}")
            elif extra and re.search(extra,l):
                print(f"  L{i+1} [{fn(i)}] {l.strip()[:120]}")
analyze('drivers/watchdog/pcwd.c', r'pcwd_private\.io_lock', extra=r'timer_setup|mod_timer|del_timer|next_heartbeat\s*=')
analyze('net/bridge/br_multicast.c', r'br->multicast_lock', extra=r'timer_setup|mod_timer|del_timer')
