import re,glob
def funcmap(path):
    src=open(path,errors='replace').read()
    defs=[]
    for m in re.finditer(r'^([A-Za-z_][A-Za-z0-9_ \t\*]*?)\s*\([^;{]*\)\s*$',src,re.M):
        name=m.group(1).split()[-1]
        brace=src.find('{',m.end())
        if brace!=-1 and src[m.end():brace].strip()=='':
            defs.append((m.start(),name,src[:m.start()].count('\n')+1))
    return src,defs
def fn(defs,pos):
    name='?'
    for s,n,l in defs:
        if s<=pos: name=n
        else: break
    return name
def show(path,lock,timer_pat=None):
    src,defs=funcmap(path)
    lines=src.split('\n')
    print("#"*12,path)
    if timer_pat:
        for i,l in enumerate(lines):
            if re.search(timer_pat,l): print(f"  TIMER L{i+1} [{fn(defs,sum(len(x)+1 for x in lines[:i]))}] {l.strip()}")
    for i,l in enumerate(lines):
        if 'spin_lock' in l and re.search(r'\(\s*&?\s*'+re.escape(lock),l):
            pos=sum(len(x)+1 for x in lines[:i])
            print(f"  L{i+1} [{fn(defs,pos)}] {l.strip()}")
show('drivers/watchdog/pcwd.c','pcwd_private.io_lock',r'timer_setup|\.function\s*=')
show('net/bridge/br_multicast.c','br->multicast_lock')
show('net/ipv6/mcast.c','ma->mca_lock',r'timer_setup|\.function\s*=')
show('drivers/mmc/host/atmel-mci.c','host->lock',r'timer_setup')
for f in glob.glob('drivers/net/wireless/iwlwifi/pcie/*.c'):
    show(f,'txq->lock')
show('net/xfrm/xfrm_state.c','x->lock',r'timer_setup')
PYEOF

